/**
 * A Work of its own, and a preview of its own to draw it on. The seeded
 * library has none -- W2 and W3 draw one, and W4 is what groups -- and a
 * frame spec that wrote to the shared database would hide two tiles from the
 * flow specs running beside it. So this is the Ranobe review's arrangement
 * (`tests/ranobe-flow.e2e.ts`): a seeded database of this file's own, and a
 * preview of the same build on its own port, with a Work made through the app and
 * left there. This preamble is hand-written; regenerating the assertions
 * below drops it (doc/WORKS.md, "The frames").
 */
const pinnedPort = Number(process.env.PLAYWRIGHT_WORKS_PORT);
const PORT =
	Number.isInteger(pinnedPort) && pinnedPort > 0 && pinnedPort <= 65535
		? pinnedPort
		: // Nothing outside this file needs the number: it seeds its own database
			// and serves it here. `PLAYWRIGHT_WORKS_PORT` pins the port when the
			// gate assigns one; unset, the OS hands out a free one, so the repo's
			// own `npx playwright test` can run the file (doc/WORKS.md, "The
			// frames"). A literal default is what two concurrent runs collide on.
			await new Promise<number>((resolve, reject) => {
				const probe = createServer();
				probe.once('error', reject);
				probe.listen(0, '127.0.0.1', () => {
					const { port } = probe.address() as AddressInfo;
					probe.close(() => resolve(port));
				});
			});
const base = `http://localhost:${PORT}`;
const dbPath = join(tmpdir(), `tsundoku-e2e-works-${process.pid}.sqlite`);
let server: ChildProcess | null = null;

/** A page of this project's own, signed in as the suite's token signs in. */
async function signedIn(browser: Browser, info: TestInfo) {
	const context = await browser.newContext({
		storageState: info.project.use.storageState as string,
		baseURL: base
	});
	const page = await context.newPage();
	return { page, close: () => context.close() };
}

test.beforeAll(async ({ browser }, info) => {
	// The hook waits up to 60 s for its own preview to answer, then makes a Work through the app:
	// past the default 30 s on a loaded box, where the hook ran out in wave
	// 24's first gate (c439), as `work-end-frame`'s did in wave 20's (c477).
	// Measured in wave 25 at a load of about 30 (the works-frame project, 3
	// copies): 5.8-7.1 s. So 60 s for the preview plus 60 s for the Work. In a hook, test.setTimeout sets the
	// hook's own budget (Playwright's test.d.ts, "Changing timeout for a
	// beforeAll").
	test.setTimeout(120_000);
	rmSync(dbPath, { force: true });
	execFileSync(process.execPath, ['--experimental-strip-types', 'scripts/seed.ts'], {
		env: { ...process.env, DATABASE_PATH: dbPath, NODE_NO_WARNINGS: '1' },
		stdio: 'pipe'
	});
	server = spawn('npx', ['vite', 'preview', '--port', String(PORT), '--strictPort'], {
		env: {
			...process.env,
			DATABASE_PATH: dbPath,
			TSUNDOKU_TOKEN: E2E_TOKEN,
			TSUNDOKU_ANILIST: 'off',
			LIBRARY_ROOT: join(tmpdir(), `tsundoku-e2e-works-empty-${process.pid}`),
			TSUNDOKU_HOME: join(tmpdir(), `tsundoku-e2e-works-home-${process.pid}`)
		},
		stdio: 'ignore'
	});
	let up = false;
	for (let i = 0; i < 120 && !up; i++) {
		try {
			up = (await fetch(`${base}/`, { redirect: 'manual' })).status > 0;
		} catch {
			await new Promise((r) => setTimeout(r, 500));
		}
	}
	if (!up) throw new Error('the works preview never answered');

	// Two in progress and among the seed's newest reads, so the Work is near
	// the top of CONTINUE. They are only this file's: the database is its own.
	const { page, close } = await signedIn(browser, info);
	await page.goto('/');
	// A page of this file's own context: its `goto` is Playwright's, with
	// none of the fixtures' hydration wait, and SELECT pressed before the
	// page hydrated did nothing, so GROUP never came (c439: the hook ran out
	// its 120 s in wave 25's loaded run).
	await hydrated(page);
	await page.getByRole('button', { name: 'SELECT', exact: true }).click();
	const tile = (title: string) =>
		page.locator('.grid .tile').filter({
			has: page.locator('.title', { hasText: new RegExp(`^${title}$`) })
		});
	for (const title of ["Omniscient Reader's Viewpoint", 'Hoshi no Umi no Tabibito'])
		await tile(title).locator('.open').click();
	// W4's AS sheet is how a Work is made now: GROUP, A WORK, a name, CREATE.
	await page.getByRole('button', { name: 'GROUP', exact: true }).click();
	const sheet = page.getByRole('dialog', { name: 'Group into a series' });
	await expect(sheet).toBeVisible();
	await sheet.getByRole('radio', { name: /A WORK · SERIES/ }).click();
	await sheet.getByRole('textbox', { name: 'Work name' }).fill('Frame Run');
	await sheet.getByRole('button', { name: /CREATE WORK/ }).click();
	await expect(page.locator('.band', { hasText: 'FRAME RUN IS A WORK' })).toBeVisible();
	await page.locator('.grid .tile.work', { hasText: 'Frame Run' }).click();
	await page.waitForURL(/\/work\/\d+/);
	workId = Number(/\/work\/(\d+)/.exec(page.url())?.[1]);
	await close();
	expect(workId).toBeGreaterThan(0);
});

test.afterAll(() => {
	server?.kill();
	server = null;
	rmSync(dbPath, { force: true });
});

