test('The Work screen: panel matches the handoff', async ({ page }) => {
	await page.goto(`${base}/work/${workId}`);
	await expect(page.locator(SEL.panel).first()).toBeVisible();

	const panelStyle = await page
		.locator(SEL.panel)
		.first()
		.evaluate((node) => {
			const cs = getComputedStyle(node);
			return {
				display: cs.display,
				flexDirection: cs.flexDirection,
				borderRightWidth: cs.borderRightWidth
			};
		});
	expect(panelStyle.display).toBe('flex');
	expect(panelStyle.flexDirection).toBe('column');
	expect(panelStyle.borderRightWidth).toBe('1px');
});

